import{_ as t,o as d,c as a,az as o}from"./chunks/framework.N1XcotCa.js";const m=JSON.parse('{"title":"Tool Reference","description":"","frontmatter":{},"headers":[],"relativePath":"mcp/tools.md","filePath":"mcp/tools.md"}'),r={name:"mcp/tools.md"};function s(c,e,i,l,n,h){return d(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="tool-reference" tabindex="-1">Tool Reference <a class="header-anchor" href="#tool-reference" aria-label="Permalink to “Tool Reference”">​</a></h1><p>The server exposes six tools. Each is a thin wrapper over the <a href="/api/">REST API</a> — same validation, same credits, same results — so anything an agent does here is equivalent to the matching REST call.</p><h2 id="workflow" tabindex="-1">Workflow <a class="header-anchor" href="#workflow" aria-label="Permalink to “Workflow”">​</a></h2><ol><li><a href="#list-templates"><code>list-templates</code></a> / <a href="#list-models"><code>list-models</code></a> — discover what&#39;s available.</li><li><a href="#get-template"><code>get-template</code></a> — see the inputs a template accepts.</li><li><a href="#generate-image"><code>generate-image</code></a> — start a generation; returns a task id with status <code>created</code>.</li><li><a href="#get-task"><code>get-task</code></a> — poll until status is <code>success</code> and read the image URLs. <a href="#list-tasks"><code>list-tasks</code></a> reviews earlier runs.</li></ol><h2 id="list-templates" tabindex="-1"><code>list-templates</code> <a class="header-anchor" href="#list-templates" aria-label="Permalink to “list-templates”">​</a></h2><p>Lists the templates available to the account — its own plus public presets — each with its id, name, description, thumbnail, and model.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>s</code></td><td>string</td><td>Search templates by name.</td></tr><tr><td><code>ownership</code></td><td>string</td><td><code>all</code> (default), <code>public</code>, or <code>private</code>.</td></tr><tr><td><code>model_id</code></td><td>integer</td><td>Only templates using this model.</td></tr><tr><td><code>per_page</code></td><td>integer</td><td>Results per page (1–100, default 15).</td></tr><tr><td><code>page</code></td><td>integer</td><td>Page number.</td></tr></tbody></table><p>Returns a paginated list of templates. REST equivalent: <a href="/api/templates"><code>GET /templates</code></a>.</p><h2 id="get-template" tabindex="-1"><code>get-template</code> <a class="header-anchor" href="#get-template" aria-label="Permalink to “get-template”">​</a></h2><p>Full detail for one template, including the exact inputs it accepts: <code>default_inputs</code>, the model&#39;s <code>input</code> schema, and any <code>prompt_variables</code>. Call this before <code>generate-image</code>.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>template_id</code></td><td>string · <strong>required</strong></td><td>Template UUID (from <code>list-templates</code>).</td></tr></tbody></table><p>Returns the full template. REST equivalent: <a href="/api/templates"><code>GET /templates/{template}</code></a>.</p><h2 id="list-models" tabindex="-1"><code>list-models</code> <a class="header-anchor" href="#list-models" aria-label="Permalink to “list-models”">​</a></h2><p>Lists the available models and each model&#39;s <code>input</code> schema — the fields <code>generate-image</code> accepts when called with a <code>model_id</code>.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>s</code></td><td>string</td><td>Search models by name.</td></tr><tr><td><code>owner</code></td><td>string</td><td>Filter by owner / provider slug (e.g. <code>openai</code>).</td></tr><tr><td><code>sort_by</code></td><td>string</td><td><code>created_at</code> (default) or <code>name</code>.</td></tr><tr><td><code>sort_direction</code></td><td>string</td><td><code>asc</code> or <code>desc</code> (default <code>desc</code>).</td></tr></tbody></table><p>Returns a paginated list of models. REST equivalent: <a href="/api/models"><code>GET /models</code></a>.</p><h2 id="generate-image" tabindex="-1"><code>generate-image</code> <a class="header-anchor" href="#generate-image" aria-label="Permalink to “generate-image”">​</a></h2><p>Starts a generation from a template or a model. Asynchronous: returns a task id with status <code>created</code>. Poll <a href="#get-task"><code>get-task</code></a> for the result. Charges credits.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>template_id</code></td><td>string</td><td>Template UUID to generate from. Provide this <strong>or</strong> <code>model_id</code>, not both.</td></tr><tr><td><code>model_id</code></td><td>integer</td><td>Model id to generate from directly, instead of a template.</td></tr><tr><td><code>inputs</code></td><td>object</td><td>Generation inputs the template/model accepts — e.g. <code>prompt</code>, <code>image_urls</code>, <code>image_size</code>. See <code>get-template</code> (<code>model.input</code>) for the accepted fields.</td></tr><tr><td><code>variables</code></td><td>object</td><td>Values for the template&#39;s prompt variables, as key → value.</td></tr><tr><td><code>provider_id</code></td><td>integer</td><td>Force a specific provider; omit to auto-select.</td></tr></tbody></table><p>Returns the created task. REST equivalent: <a href="/api/process"><code>POST /process</code></a>.</p><h2 id="get-task" tabindex="-1"><code>get-task</code> <a class="header-anchor" href="#get-task" aria-label="Permalink to “get-task”">​</a></h2><p>Status and result of one generation. While running, status is <code>created</code> or <code>processing</code>; when <code>success</code>, the response includes the output image URLs.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>task_id</code></td><td>string · <strong>required</strong></td><td>Task id from <code>generate-image</code>.</td></tr></tbody></table><p>Returns the task with its status and, when finished, output images. REST equivalent: <a href="/api/tasks"><code>GET /tasks/{task}</code></a>.</p><h2 id="list-tasks" tabindex="-1"><code>list-tasks</code> <a class="header-anchor" href="#list-tasks" aria-label="Permalink to “list-tasks”">​</a></h2><p>The account&#39;s generation tasks, most recent first, with status and model. Filter to review a batch — e.g. failed runs from one template.</p><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>status</code></td><td>string</td><td><code>created</code>, <code>processing</code>, <code>success</code>, or <code>error</code>.</td></tr><tr><td><code>template_id</code></td><td>string</td><td>Only tasks from this template (UUID).</td></tr><tr><td><code>model_id</code></td><td>integer</td><td>Only tasks from this model id.</td></tr><tr><td><code>per_page</code></td><td>integer</td><td>Results per page (1–100, default 15).</td></tr><tr><td><code>page</code></td><td>integer</td><td>Page number.</td></tr></tbody></table><p>Returns a paginated list of tasks. REST equivalent: <code>GET /tasks</code>.</p>',28)])])}const g=t(r,[["render",s]]);export{m as __pageData,g as default};
